"use client";

import type { ComponentProps } from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BADGE_SIZE, useBarSize } from "./barSize";

/**
 * src/components/badge.tsx — a plain, stock shadcn Badge. Not vendored
 * anywhere else in this repo (checked apps/docs and packages/inspector —
 * absent from both), so this is written fresh rather than ported; it's a
 * small, extremely standard shadcn primitive with nothing repo-specific to
 * preserve. No `asChild`/Slot support — this app has no reason yet to
 * render a Badge as a link, and skipping it avoids a new dependency.
 *
 * WHY `size` was added here (stock shadcn's Badge has none): the Bar size
 * cascade (barSize.tsx) needs somewhere to land on Badge, and there was no
 * existing scale to hook into. Four rungs, matching `Bar`'s own directly.
 *
 * WHY `shape` defaults to `"rounded"` rather than flipping to pill
 * (docs/FEEDBACK-2026-09-17b-PLAN.md A-1, Zach: "show some badges with a
 * more pill shape"): he asked to *see* the pill option, not replace the
 * landed look — every existing caller (in particular `Bar`'s title badge,
 * which reads as a chip on purpose) must render unchanged. `rounded-full`
 * is opt-in via `shape="pill"`, not the new floor.
 */
const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border font-medium whitespace-nowrap transition-[color,box-shadow] [&>svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground",
        secondary: "border-transparent bg-secondary text-secondary-foreground",
        destructive: "border-transparent bg-destructive text-white dark:bg-destructive/60",
        outline: "text-foreground",
      },
      size: {
        sm: "gap-0.5 px-1.5 py-0 text-[0.65rem] [&>svg]:size-2.5",
        md: "gap-1 px-2 py-0.5 text-xs [&>svg]:size-3",
        lg: "gap-1 px-2.5 py-1 text-sm [&>svg]:size-3.5",
        xl: "gap-1.5 px-3 py-1 text-base [&>svg]:size-4",
      },
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
      shape: "rounded",
    },
  },
);

export interface BadgeProps extends ComponentProps<"span">, VariantProps<typeof badgeVariants> {}

export function Badge({ className, variant, size, shape, ...props }: BadgeProps) {
  // Explicit `size` wins; the ambient Bar cascade is only the fallback when
  // `size` itself is omitted, `"md"` (cva's own default) is the floor when
  // there is no Bar ancestor either.
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BADGE_SIZE[barSize]) ?? "md";
  return (
    <span
      data-slot="badge"
      data-size={resolvedSize}
      data-shape={shape ?? "rounded"}
      className={cn(badgeVariants({ variant, size: resolvedSize, shape }), className)}
      {...props}
    />
  );
}

export { badgeVariants };

import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";
import { BarSizeProvider } from "./barSize";

/**
 * Bar — a horizontal strip with three slots (left · center · right).
 * Structure is unchanged from the reset: no appearance cascade, no
 * tone/state, just the three slots. What changed in the shadcn/Tailwind
 * migration is HOW it's painted — Tailwind utilities against the shadcn CSS
 * variables in src/globals.css instead of raw `style={{...}}` colors,
 * borrowing the visual vocabulary (not the props) of
 * packages/bbox-ui/src/bar.tsx.
 *
 * WHY the grid template is COMPUTED, not a fixed `1fr auto 1fr` (Zach: "if
 * the center slot is empty or so, then things in the other slots should
 * just continue to expand width wise, and not truncate. Unless you
 * specifically set a width limit"): `1fr auto 1fr` forces the left/right
 * tracks to stay EQUAL width even when one of them (or center) is empty —
 * that symmetry is exactly what real centering needs, but it also means an
 * empty center/right still claims (and wastes) half the bar's width, and a
 * long `left` label truncates against that artificial half-width ceiling
 * with the other half sitting empty. Measured live: a previous lane's own
 * `AllSizes` cascade cluster had already been moved from `left` to `center`
 * and its swatch widened 420→520px specifically to dodge this — a symptom
 * fix, not a cause fix, and reverted below now that the cause is fixed.
 * `barGridTemplateColumns` (below) keeps `1fr auto 1fr`'s symmetric flanks
 * ONLY when `center` actually holds content (centering is structurally
 * impossible without equal flanks, filled or not); otherwise the unused
 * slot's track collapses to `0` and `left`'s own track becomes the single
 * `1fr` that absorbs everything center/right aren't using — so it only
 * truncates once the BAR ITSELF is out of room, never before. A caller that
 * wants a truncation limit narrower than "however wide the bar naturally
 * is" sets one explicitly by wrapping its own content in a `width`-bounded
 * box — see `Bar.stories.tsx`'s `Widths` gallery — rather than `Bar`
 * growing a new prop for it.
 *
 * WHY no `rounded-lg`/`border`/`bg-card` here: a Bar is a layout strip, not
 * a card — the same way `Flex` paints nothing of its own. Zach: "I don't
 * like how the bars have these borders. they should fill the block footer
 * and headers edge to edge... the only lines are the dividers." A Bar
 * filling `Block`'s header/footer must read as flush with it, not as a
 * pill floating inside it — `Block`'s own `border-b`/`border-t` supply the
 * only lines. A standalone Bar story that wants to show the strip's own
 * extent adds a wrapper (e.g. a dashed box) at the STORY level instead.
 *
 * WHY `size` is also published via `BarSizeProvider`: Zach's size-cascade
 * ask — a Bar's contents should size themselves off the Bar's own `size`
 * rather than each getting hand-tuned. See `barSize.tsx` for the mapping
 * from these four rungs onto each consumer's own scale.
 */
function barGridTemplateColumns(hasCenter: boolean, hasRight: boolean): string {
  if (hasCenter) return "1fr auto 1fr";
  if (hasRight) return "1fr 0 auto";
  return "1fr 0 0";
}

export const BAR_SIZES = ["sm", "md", "lg", "xl"] as const;
export type BarSize = (typeof BAR_SIZES)[number];

/** Bar height per rung, px. */
export const BAR_HEIGHT: Record<BarSize, number> = { sm: 28, md: 36, lg: 48, xl: 60 };

export interface BarProps {
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
  size?: BarSize;
  style?: CSSProperties;
}

// WHY `overflow-clip` + a 4px `overflow-clip-margin` instead of plain
// `overflow-hidden`: a focusable control flush against a cell's edge (a
// left-slot FoldingChevron, a right-slot Toggle/Button) paints its
// focus-visible ring OUTSIDE its own border box — `hidden` clips that ink
// the instant it crosses the cell boundary, which is the actual cause of
// the bug Zach reported ("chevron has a box cut off on its left") and,
// measured live, hits any focusable control sitting flush at a cell edge,
// not just the chevron. `overflow-clip-margin` is the CSS-spec-native fix:
// it only relaxes where PAINT (ink like a box-shadow ring or an outline) is
// allowed to bleed past the clip box, layout overflow — the thing this
// class exists to contain, e.g. EditableText's own `minWidth:0`/ellipsis
// truncation still clips flush at (edge + 4px). 4px covers both the
// shadcn ring-3 box-shadow (3px spread, 0 offset) and the browser's native
// default outline that a bare-button control like FoldingChevron falls
// back to. Only takes effect on `overflow: clip` (not `hidden`), which is
// otherwise behaviourally identical for this cell's purposes — no scroll
// either way.
const cellClass = "flex min-w-0 items-center overflow-clip [overflow-clip-margin:4px]";

export function Bar({ left, center, right, size = "md", style }: BarProps) {
  return (
    <BarSizeProvider size={size}>
      <div
        data-slot="bar"
        data-size={size}
        // WHY `group`: a plain Tailwind marker class, paints nothing on its
        // own — it exists so a `FoldingChevron reveal="hover"` inside this
        // Bar can key its `group-hover`/`group-focus-within` reveal off the
        // Bar itself ("the surrounding region... the Bar/header it lives
        // in", not the 24px button). Harmless for every Bar that has no
        // such child.
        className={cn("group grid w-full items-center gap-2 px-3 text-sm text-card-foreground")}
        style={{
          gridTemplateColumns: barGridTemplateColumns(center !== undefined, right !== undefined),
          height: BAR_HEIGHT[size],
          ...style,
        }}
      >
        <div data-slot="bar-left" className={cn(cellClass, "justify-start")}>
          {left}
        </div>
        <div data-slot="bar-center" className={cn(cellClass, "justify-center")}>
          {center}
        </div>
        <div data-slot="bar-right" className={cn(cellClass, "justify-end")}>
          {right}
        </div>
      </div>
    </BarSizeProvider>
  );
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

import type { BarSize } from "./bar";
import type { EditableTextSize } from "./editableText.layout";
import type { GlyphSize } from "./glyph.layout";

/**
 * src/components/barSize.tsx — the size CASCADE from `Bar` down to its own
 * contents. Zach: "various things inside of the bar will size themselves
 * correctly... with a 'large bar' vs small bar you don't need to hand tune
 * each element inside." A React context, mirroring `glyph.tsx`'s own
 * resolver-context pattern (provider + `use*` hook), not a new prop
 * threaded through every layer in between — `Bar` already owns a `size`
 * prop (bar.tsx); this only makes that value reach descendants.
 *
 * The mapping from Bar's four rungs (sm/md/lg/xl) onto each consumer's OWN
 * size scale lives HERE, in one place, rather than scattered per component.
 * `Glyph`/`EditableText` already share Bar's exact four-rung ladder, so
 * their mapping is the identity — still spelled out below so all five
 * mappings are visible in one lookup. `Badge`/`Button`/`Toggle` each carry
 * a differently-shaped scale of their own.
 *
 * An explicit size prop on any child ALWAYS wins — every consumer only
 * calls into this context as the fallback when its own prop is
 * `undefined`, same "explicit beats derived" rule `glyphFootprint` already
 * applies to its own size/sizePreset pair.
 */

const BarSizeContext = createContext<BarSize | undefined>(undefined);

/** Mounted by `Bar` itself (bar.tsx) — not meant to be reached for by callers. */
export function BarSizeProvider({ size, children }: { size: BarSize; children?: ReactNode }) {
  return <BarSizeContext.Provider value={size}>{children}</BarSizeContext.Provider>;
}

/** `undefined` outside any `Bar` — "not inside a cascade," not an error;
 *  same shape as `useGlyphResolver`'s "no provider mounted" case. */
export function useBarSize(): BarSize | undefined {
  return useContext(BarSizeContext);
}

/** Glyph's own ladder (glyph.layout.ts's `GLYPH_SIZES`) is identical to
 *  Bar's four rungs, so the cascade is the identity. */
export const BAR_SIZE_TO_GLYPH_PRESET: Record<BarSize, GlyphSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** EditableText's own ladder (editableText.layout.ts's `EDITABLE_TEXT_SIZES`)
 *  is the same four-rung ladder too — see that file's own comment on why
 *  Glyph/EditableText/Port each keep an independent ladder rather than
 *  sharing one, even though the VALUES line up. */
export const BAR_SIZE_TO_EDITABLE_TEXT_SIZE: Record<BarSize, EditableTextSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Badge has no size scale of its own yet (badge.tsx was a plain stock
 *  shadcn Badge, one size only) — this cascade is what gives it one,
 *  matching Bar's own four rungs directly. */
export type BadgeSize = "sm" | "md" | "lg" | "xl";
export const BAR_SIZE_TO_BADGE_SIZE: Record<BarSize, BadgeSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Button and Toggle each already ship a THREE-rung size scale
 *  (sm/default/lg — no "xl"), so Bar's `xl` clamps down to their largest
 *  rung rather than this cascade inventing a fourth one they don't have. */
export type ButtonToggleSize = "sm" | "default" | "lg";
export const BAR_SIZE_TO_BUTTON_SIZE: Record<BarSize, ButtonToggleSize> = {
  sm: "sm",
  md: "default",
  lg: "lg",
  xl: "lg",
};
export const BAR_SIZE_TO_TOGGLE_SIZE: Record<BarSize, ButtonToggleSize> = BAR_SIZE_TO_BUTTON_SIZE;

// src/components/branchChip.tsx — the draft/branch selector beside the file
// title (docs/menus/screenshots/05-chrome-bar.png's "Main ▾", 09's outlined
// "Draft 1 (1) ▾"). Ported from
// /home/bam/systemsketch/src/drafts/DraftsControl.tsx:1-307 — the two-step
// "Discard?" confirm, the hover-revealed row actions, the explicit
// `${name}, ${secondary}` aria-label (adjacent `<b>`/`<small>` have no
// whitespace between them in the accessible-name computation), the
// `renderTrigger` re-skin seam, and the "no version has ever been pinned so
// `baseLabel` is fabricated" secondary-label guard all travel; the popover
// primitive, the rename field, and the drafts DATA (`DraftProvider`,
// `useDrafts`, `draftModel.ts`) do not — this component takes
// `DraftSummary[]`/callbacks instead (MENU-KIT-DESIGN.md §7:
// "`draftModel.ts` state reducers... are SystemSketch's localStorage
// branching bookkeeping. The kit ships the `DraftSummary` prop shape only").
"use client";

import { useState, type ReactElement } from "react";
import { ChevronDown, GitBranch, Pencil, Plus, Trash2 } from "lucide-react";

import { cn } from "../lib/utils";
import { Badge } from "./badge";
import { Button, buttonVariants } from "./button";
import { InlineRename } from "./inlineRename";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

export interface DraftSummary {
  id: string;
  name: string;
  /** Computed host-side, deliberately — the donor's own `baseLabel` is
   *  fabricated the moment no version has ever been pinned (every draft
   *  read "based on v0.1" whether or not that meant anything); this kit
   *  refuses to guess and takes the finished string instead. */
  secondaryLabel: string;
}

export interface BranchChipProps {
  isDraftMode: boolean;
  draftCount: number;
  activeDraftName: string | null;
  drafts: readonly DraftSummary[];
  activeDraftId: string | null;
  onSwitchTo(id: string | null): void;
  onCreate(): void;
  onRename(id: string, name: string): void;
  onDiscard(id: string): void;
  /** The proven re-skin seam (DraftsControl.tsx:213-224): a caller supplies
   *  its own trigger without forking the popover. Receives the same state
   *  the default trigger renders from, so a host can compose it with
   *  `ToolbarButton`/`DropdownMenuTrigger` the way `chromeBar.tsx` composes
   *  every other bar control, without this file importing `toolbar.tsx`
   *  itself — `BranchChip` has no opinion on whether it lives inside a
   *  `Toolbar` at all (the gallery below shows it standalone). */
  renderTrigger?: (state: {
    isDraftMode: boolean;
    draftCount: number;
    activeDraftName: string | null;
  }) => ReactElement;
  container?: HTMLElement | null;
}

/**
 * Just the icon/name/badge/chevron — never the trigger element itself.
 *
 * WHY the default arm renders these as `PopoverTrigger`'s CHILDREN rather
 * than composing a separate `<Button render={...}/>` the way `chromeBar.tsx`
 * composes its own controls: `Button` (and every plain function component in
 * this kit) forwards unknown props via `{...props}`, which is what makes it
 * safe as a `render` TARGET — but this content is never one. Wrapping it in
 * an extra component here would put a non-forwarding function component
 * BETWEEN `PopoverTrigger` and its real props (onClick, `aria-expanded`,
 * `data-popup-open`, the ref Base UI's positioner anchors to), silently
 * dropping all of them the moment that wrapper's own signature doesn't
 * spread `...rest` onto something real. `PopoverTrigger` styled directly
 * (below) IS the host button; nothing sits between it and Base UI.
 */
function DefaultTriggerContent({
  draftCount,
  activeDraftName,
}: {
  draftCount: number;
  activeDraftName: string | null;
}) {
  return (
    <>
      <GitBranch aria-hidden="true" className="size-3.5" />
      <span className="max-w-32 truncate">{activeDraftName ?? "Main"}</span>
      {draftCount > 0 ? (
        <Badge variant="secondary" size="sm" shape="pill">
          {draftCount}
        </Badge>
      ) : null}
      <ChevronDown aria-hidden="true" className="size-3.5 opacity-60" />
    </>
  );
}

/**
 * One row: Main, or a draft with rename + a two-step discard.
 *
 * WHY discard is a two-step confirm inline in the row rather than a dialog
 * (ported, DraftsControl.tsx:128-134): this popover already renders as
 * floating chrome above the canvas, not inside a dialog stack — one local
 * pattern (`Trash2` → "Discard?" → click again) keeps "discard a draft"
 * behaving identically everywhere it appears instead of a modal in one
 * place and something else in another. Resets `onBlur` so a confirm state
 * never survives the row losing focus.
 */
function DraftRow({
  draft,
  isCurrent,
  onSelect,
  onRename,
  onDiscard,
}: {
  draft: DraftSummary;
  isCurrent: boolean;
  onSelect(): void;
  onRename(name: string): void;
  onDiscard(): void;
}) {
  const [renaming, setRenaming] = useState(false);
  const [confirmingDiscard, setConfirmingDiscard] = useState(false);

  if (renaming) {
    return (
      <div
        data-slot="branch-chip-row"
        data-current={isCurrent || undefined}
        className="flex items-center gap-2 rounded-md px-2 py-1.5"
      >
        <GitBranch aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
        <InlineRename
          value={draft.name}
          onCommit={(next) => {
            onRename(next);
            setRenaming(false);
          }}
          onCancel={() => setRenaming(false)}
          size="row"
          aria-label={`Rename ${draft.name}`}
          className="flex-1"
        />
      </div>
    );
  }

  return (
    <div
      data-slot="branch-chip-row"
      data-current={isCurrent || undefined}
      // WHY the actions are hover-revealed (`group` + `opacity-0
      // group-hover:opacity-100`) rather than always visible (ported,
      // DraftsControl.tsx's `.systemsketch-drafts-row__actions`): a list of
      // drafts is scanned by name far more often than acted on — two
      // buttons per row, always on, is noise the whole rest of the time.
      className="group flex items-center gap-1 rounded-md px-1 py-0.5 hover:bg-muted data-current:bg-accent/50"
    >
      <button
        type="button"
        onClick={onSelect}
        data-testid={`branch-chip-select-${draft.id}`}
        // WHY the accessible name is spelled out explicitly rather than
        // read from the row's own text nodes (ported verbatim,
        // DraftsControl.tsx:173-176): adjacent `<b>`/`<small>` are block-
        // adjacent with no whitespace between them in the accessible-name
        // computation ("Draft 1based on v0.1").
        aria-label={`${draft.name}, ${draft.secondaryLabel}`}
        className="flex min-w-0 flex-1 items-center gap-2 rounded px-1 py-1 text-left"
      >
        <GitBranch aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
        <span className="flex min-w-0 flex-col">
          <b className="truncate text-sm font-medium">{draft.name}</b>
          <small className="truncate text-xs text-muted-foreground">{draft.secondaryLabel}</small>
        </span>
      </button>
      <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100">
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label={`Rename ${draft.name}`}
          onClick={() => {
            setConfirmingDiscard(false);
            setRenaming(true);
          }}
        >
          <Pencil aria-hidden="true" />
        </Button>
        <Button
          type="button"
          variant={confirmingDiscard ? "destructive" : "ghost"}
          size={confirmingDiscard ? "xs" : "icon-xs"}
          aria-label={confirmingDiscard ? `Confirm discard ${draft.name}` : `Discard ${draft.name}`}
          onClick={() => {
            if (confirmingDiscard) onDiscard();
            else setConfirmingDiscard(true);
          }}
          onBlur={() => setConfirmingDiscard(false)}
        >
          {confirmingDiscard ? "Discard?" : <Trash2 aria-hidden="true" />}
        </Button>
      </div>
    </div>
  );
}

export function BranchChip({
  isDraftMode,
  draftCount,
  activeDraftName,
  drafts,
  activeDraftId,
  onSwitchTo,
  onCreate,
  onRename,
  onDiscard,
  renderTrigger,
  container,
}: BranchChipProps) {
  const [open, setOpen] = useState(false);
  const triggerState = { isDraftMode, draftCount, activeDraftName };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      {renderTrigger ? (
        <PopoverTrigger render={renderTrigger(triggerState)} />
      ) : (
        <PopoverTrigger
          type="button"
          // WHY `data-active` is `isDraftMode || undefined` rather than the
          // boolean itself (ported verbatim, TitleBar.tsx:484-488 /
          // DraftsControl.tsx:251): Tailwind's bare `data-active:` variant
          // is a PRESENCE test — `data-active="false"` still matches it and
          // lights the chip up off-draft. `undefined` drops the attribute.
          data-active={isDraftMode || undefined}
          // WHY the outline is a `data-active:` variant on a semantic token
          // (`border-primary`/`text-primary`) rather than a literal colour:
          // the design brief's own instruction — draft-mode-active is DATA,
          // the pixels are the theme's.
          className={cn(
            buttonVariants({ variant: "outline", size: "sm" }),
            "gap-1.5 px-2 text-inherit data-active:border-primary data-active:text-primary data-active:ring-1 data-active:ring-primary/30",
          )}
          aria-label={isDraftMode ? `Draft ${activeDraftName}` : "Drafts · Main"}
        >
          <DefaultTriggerContent draftCount={draftCount} activeDraftName={activeDraftName} />
        </PopoverTrigger>
      )}
      <PopoverContent container={container} align="start" className="w-64" aria-label="Drafts">
        <p className="text-sm font-semibold">Drafts</p>
        <div className="flex flex-col gap-0.5" data-slot="branch-chip-list">
          <button
            type="button"
            data-current={activeDraftId === null || undefined}
            data-testid="branch-chip-select-main"
            className="flex items-center gap-2 rounded-md px-1 py-1.5 text-left hover:bg-muted data-current:bg-accent/50"
            onClick={() => {
              onSwitchTo(null);
              setOpen(false);
            }}
          >
            <GitBranch aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
            <b className="text-sm font-medium">Main</b>
          </button>
          {drafts.map((draft) => (
            <DraftRow
              key={draft.id}
              draft={draft}
              isCurrent={draft.id === activeDraftId}
              onSelect={() => {
                onSwitchTo(draft.id);
                setOpen(false);
              }}
              onRename={(name) => onRename(draft.id, name)}
              onDiscard={() => onDiscard(draft.id)}
            />
          ))}
        </div>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className={cn("justify-start gap-1.5")}
          data-testid="branch-chip-new-draft"
          onClick={() => {
            onCreate();
            setOpen(false);
          }}
        >
          <Plus aria-hidden="true" />
          New draft
        </Button>
      </PopoverContent>
    </Popover>
  );
}

"use client";

// src/components/button.tsx — copied verbatim from
// apps/docs/src/registry/new-york-v4/ui/button.tsx (the stock shadcn `new-york`
// Button over Base UI), only the `cn` import path changed to match this app,
// plus the Bar size cascade (barSize.tsx) below.
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BUTTON_SIZE, useBarSize } from "./barSize";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
